export const stories = raw.map((s) => {
  const words = wordCount(s.text);
  return {
    ...s,
    wordCount: words,
    readMinutes: Math.max(1, Math.round(words / READ_WPM)),
    listenMinutes: Math.max(1, Math.round(words / LISTEN_WPM)),
  };
});

export function getStoryById(id) {
  return stories.find((s) => s.id === id);
}
